using Hyper.Domain.Entities.Integrations; namespace Hyper.Domain.Features.Integrations; public sealed record IntegrationEventEnvelope(string EventId,string EventType,string Provider,string TenantId,int ShopId,string PayloadJson,string Source,string? CorrelationId,DateTime OccurredAtUtc); public interface IIntegrationStrategyResolver { IExternalIntegrationAdapter Resolve(IntegrationProvider provider); } public sealed class IntegrationStrategyResolver(IEnumerable<IExternalIntegrationAdapter> adapters) : IIntegrationStrategyResolver { public IExternalIntegrationAdapter Resolve(IntegrationProvider provider)=>adapters.SingleOrDefault(x=>x.Provider==provider) ?? throw new InvalidOperationException($"No adapter registered for provider {provider}"); }
